import {questions,scriptureReference} from './questions.js';
const app=document.querySelector('#app');
let screen='home',index=0,score=0,remaining=30,chosen=null,answers=[],interval,deadline,sound=false,audio;
const letters=['A','B','C','D'];
const sword=`<svg viewBox="0 0 180 210" aria-hidden="true"><g fill="none" stroke-linejoin="miter"><path d="M89 18 104 39 98 130 83 130 77 39Z" fill="#d9fcff" stroke="#73e9ff" stroke-width="3"/><path d="M89 28V130" stroke="#6b83da" stroke-width="3"/><path d="M58 127 69 120 83 132H98L112 120 123 127 109 144H72Z" fill="#f5c560" stroke="#fff0ac" stroke-width="3"/><path d="M84 145H98V179H84Z" fill="#9b51bb" stroke="#f49ad8" stroke-width="3"/><path d="M80 183 91 193 102 183 98 177H84Z" fill="#f5c560" stroke="#fff0ac" stroke-width="3"/></g></svg>`;
function beep(kind='click'){if(!sound)return;try{audio??=new AudioContext();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.setValueAtTime(kind==='correct'?660:kind==='wrong'?150:440,audio.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='correct'?990:220,audio.currentTime+.15);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.23)}catch{}}
function stop(){clearInterval(interval)}
function start(){stop();index=0;score=0;answers=[];screen='quiz';newQuestion()}
function newQuestion(){chosen=null;remaining=30;deadline=Date.now()+30000;render();interval=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));const clock=document.querySelector('#clock');if(clock){clock.textContent=String(remaining).padStart(2,'0');clock.parentElement.classList.toggle('urgent',remaining<=10)}const bar=document.querySelector('#time-fill');if(bar)bar.style.width=`${remaining/30*100}%`;if(!remaining)answer(-1)},150)}
function answer(value){if(screen!=='quiz'||chosen!==null)return;stop();chosen=value;const correct=value===questions[index].answer;if(correct)score+=100;answers.push({chosen:value,correct});beep(correct?'correct':'wrong');render();document.querySelector('#next').focus()}
function next(){if(index===questions.length-1){screen='result';render();document.querySelector('h1').focus()}else{index++;newQuestion()}}
function home(){stop();screen='home';render()}
function render(){if(screen==='home')app.innerHTML=`<section class="intro"><div class="live"><i></i> NOW PLAYING <span>THE BIBLE KNOWLEDGE CHALLENGE</span></div><div class="hero-layout"><div class="hero-copy"><p class="eyebrow">STEP INTO THE LIGHT. STAND ON THE WORD.</p><h1>LIONS GATE<span>SWORD<br>SHARPENER<span class="spark">✦</span></span></h1><p class="lead">Put your knowledge to the test.<br>Ten questions. One spotlight. Stay sharp.</p><div class="actions"><button class="primary" id="start">START GAME <span>▶</span></button><button class="text-button" id="how">HOW TO PLAY ↗</button></div><p class="coin">NO COINS NEEDED. JUST YOUR KNOWLEDGE.</p></div><div class="stage" aria-label="Neon sword on a game show stage"><div class="stage-top">✦ &nbsp; THE WORD IS YOUR WEAPON &nbsp; ✦</div><div class="arch"><div class="arch-inner"><div class="rays"></div><div class="sword">${sword}</div><span class="star s1">✧</span><span class="star s2">✦</span><span class="star s3">✧</span><div class="stage-title">STAY<br><strong>SHARP.</strong></div><div class="stage-sub">KNOW IT. LIVE IT.</div></div></div><div class="podium"><span>LIONS GATE</span><div>✦ ✦ ✦</div></div><div class="floor"></div><div class="on-air"><i></i> ON AIR</div></div></div><div class="rules" id="rules"><div><span class="rule-icon">01</span><p><strong>10 QUESTIONS</strong><small>Test your knowledge of Scripture</small></p></div><div><span class="rule-icon">◷</span><p><strong>30 SECONDS EACH</strong><small>Think fast. Answer with purpose.</small></p></div><div><span class="rule-icon">✧</span><p><strong>GROW IN THE WORD</strong><small>Scripture revealed after every answer</small></p></div></div><div class="scripture-info"><span><i></i> KJV • 80-BOOK BIBLE COLLECTION</span><button id="show-sources" class="text-button">ABOUT THE SCRIPTURES ↗</button></div></section>`;
else if(screen==='quiz'){const q=questions[index],answered=chosen!==null,correct=chosen===q.answer;app.innerHTML=`<section class="game"><div class="game-heading"><button class="text-button" id="exit">← EXIT ROUND</button><span class="eyebrow">THE SWORD SHARPENER CHALLENGE</span><div class="score">SCORE <b>${String(score).padStart(4,'0')}</b></div></div><div class="question-lights">${questions.map((_,i)=>`<span class="${i===index?'current':i<index?(answers[i].correct?'won':'lost'):''}">${String(i+1).padStart(2,'0')}</span>`).join('')}</div><div class="quiz-board"><div class="board-top"><span>QUESTION ${String(index+1).padStart(2,'0')} / 10 <b>• ${q.topic}</b></span><div class="timer ${remaining<=10?'urgent':''}">◷ <strong id="clock">${String(remaining).padStart(2,'0')}</strong><small>SEC</small></div></div><div class="time-track"><div id="time-fill" style="width:${remaining/30*100}%"></div></div><h1 tabindex="-1">${q.q}</h1><div class="options">${q.options.map((o,i)=>`<button class="option ${answered?(i===q.answer?'correct':i===chosen?'incorrect':'dim'):''}" data-answer="${i}" ${answered?'disabled':''}><span>${letters[i]}</span>${o}<b>${answered&&i===q.answer?'✓':answered&&i===chosen?'×':''}</b></button>`).join('')}</div>${answered?`<div class="feedback ${correct?'good':'bad'}" role="status"><p class="eyebrow">${correct?'✓ CORRECT! +100 POINTS':chosen===-1?'◷ TIME’S UP — KEEP SHARPENING':'× NOT QUITE — KEEP SHARPENING'}</p><p><b>Correct answer: ${q.correctAnswer}</b></p><p>${q.explain}</p><strong>${scriptureReference(q)}</strong><a href="${q.scripture.url}" target="_blank" rel="noopener noreferrer">Read ${scriptureReference(q)} ↗</a></div><button id="next" class="primary">${index===9?'REVEAL FINAL SCORE':'NEXT QUESTION'} <span>→</span></button>`:`<p class="keyboard-hint">CHOOSE YOUR ANSWER <span>or press A, B, C, D</span></p>`}</div></section>`}
else app.innerHTML=`<section class="results"><p class="live">✦ &nbsp; ROUND COMPLETE &nbsp; ✦</p><p class="eyebrow">THE SPOTLIGHT IS YOURS</p><h1 tabindex="-1">${score===1000?'PERFECTLY':score>=700?'LOOKING':'KEEP'}<br><span>${score>=700?'SHARP.':'SHARPENING.'}</span></h1><div class="final-score"><span>FINAL SCORE</span><strong>${String(score).padStart(4,'0')}</strong><small>OUT OF 1,000 POINTS</small></div><p class="lead">${score/100} of 10 correct. ${score>=700?'A strong round. Keep growing in the Word.':'Every question is another opportunity to learn.'}</p><div class="actions"><button id="replay" class="primary">PLAY AGAIN <span>↻</span></button><button id="home" class="text-button">BACK TO INTRO</button></div><details><summary>REVIEW YOUR ROUND ↓</summary>${questions.map((q,i)=>`<div class="review"><span>${answers[i].correct?'✓':'×'} QUESTION ${i+1}</span><h3>${q.q}</h3><p>Your answer: ${answers[i].chosen===-1?'Time expired':q.options[answers[i].chosen]}</p><p>Correct answer: <strong>${q.options[q.answer]}</strong></p><p>${q.explain}</p><p class="reference">${scriptureReference(q)}</p><a target="_blank" rel="noopener noreferrer" href="${q.scripture.url}">Read ${scriptureReference(q)} ↗</a></div>`).join('')}</details></section>`;
app.querySelector('#start')?.addEventListener('click',()=>{beep();start()});app.querySelector('#how')?.addEventListener('click',()=>{document.querySelector('#rules').scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#rules').classList.add('highlight');setTimeout(()=>document.querySelector('#rules')?.classList.remove('highlight'),1800)});app.querySelector('#show-sources')?.addEventListener('click',()=>document.querySelector('#sources').showModal());app.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(Number(b.dataset.answer))));app.querySelector('#next')?.addEventListener('click',next);app.querySelector('#exit')?.addEventListener('click',()=>{if(confirm('Leave this round? Your current score will be reset.'))home()});app.querySelector('#replay')?.addEventListener('click',start);app.querySelector('#home')?.addEventListener('click',home);}
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();if(screen!=='quiz'||confirm('Leave this round? Your current score will be reset.'))home()});
document.querySelector('#sound').addEventListener('click',e=>{sound=!sound;e.currentTarget.textContent=`♫ SOUND ${sound?'ON':'OFF'}`;e.currentTarget.setAttribute('aria-pressed',String(sound));beep()});document.addEventListener('keydown',e=>{if(e.repeat||document.querySelector('dialog[open]'))return;if(screen==='quiz'&&chosen===null&&letters.includes(e.key.toUpperCase()))answer(letters.indexOf(e.key.toUpperCase()))});document.querySelector('#close-sources').onclick=()=>document.querySelector('#sources').close();render();
